+public class TSDBPassthroughIndexingIT extends ESSingleNodeTestCase {
+
+    public static final String MAPPING_TEMPLATE = """
+        {
+          "_doc":{
+            "properties": {
+              "@timestamp" : {
+                "type": "date"
+              },
+              "attributes": {
+                "type": "passthrough",
+                "dynamic": true,
