+                                "time_series_metric": "counter"
+                            },
+                            "rx": {
+                                "type": "long",
+                                "time_series_metric": "counter"
+                            }
+                        }
+                    }
+                }
+              }
+            }
+          }
+        }""";
+
+    private static final String DOC = """
+        {
+            "@timestamp": "$time",
+            "attributes": {
+                "metricset": "pod",
+                "pod": {
+                    "name": "$name",
+                    "uid": "$uid",
+                    "ip": "$ip"
+                }
+            },
